-- Core configurations (Managed by Git)
-- Generated by hyprlang2lua. Review TODOs before reloading Hyprland.

local hypr = os.getenv("HOME") .. "/.config/hypr/"
local function source(rel)
    local chunk, err = loadfile(hypr .. rel)
    if not chunk then error(err) end
    chunk()
end

source("conf.d/variables.lua")
source("conf.d/environment.lua")
source("conf.d/autostart.lua")
source("conf.d/appearance.lua")
source("conf.d/input.lua")
source("conf.d/keybinds.lua")
source("conf.d/rules.lua")
source("workspaces.lua")

-- Load all local overrides
-- This will load any .conf file inside the local folder
for _, f in ipairs({ "local/extra_environment.lua", "local/extra_keybinds.lua", "local/autostart.lua" }) do source(f) end

-- Display Settings
source("monitors.lua")
